import re

_HEADER_RE = re.compile(r'^([a-z]+)(?:\(([^()]+)\))?(!)?: (\S.*)$')

_VERSION_RE = re.compile(r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$')


def _parse_version(current):
    m = _VERSION_RE.match(current)
    if not m:
        raise ValueError("invalid version: %r" % (current,))
    return int(m.group(1)), int(m.group(2)), int(m.group(3))


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    major, minor, patch = _parse_version(current)

    NONE, FIX, FEATURE, BREAKING = 0, 1, 2, 3
    level = NONE

    for msg in commits:
        lines = msg.split("\n")
        header = lines[0]
        m = _HEADER_RE.match(header)
        if not m:
            continue

        ctype = m.group(1)
        breaking = m.group(3) == "!"

        if not breaking:
            for line in lines[1:]:
                if line.startswith("BREAKING CHANGE: ") or line.startswith("BREAKING-CHANGE: "):
                    breaking = True
                    break

        if breaking:
            level = max(level, BREAKING)
        elif ctype == "feat":
            level = max(level, FEATURE)
        elif ctype == "fix":
            level = max(level, FIX)

    if level == NONE:
        return current

    if major >= 1:
        if level == BREAKING:
            return "%d.0.0" % (major + 1)
        if level == FEATURE:
            return "%d.%d.0" % (major, minor + 1)
        return "%d.%d.%d" % (major, minor, patch + 1)
    else:
        if level == BREAKING:
            return "0.%d.0" % (minor + 1)
        return "0.%d.%d" % (minor, patch + 1)
